CREATE TABLE IF NOT EXISTS public.ecosystem_investor_match_scores (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), investor_profile_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, eco_partner_profile_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, fit_score INTEGER NOT NULL CHECK (fit_score >= 0 AND fit_score <= 100), summary TEXT, rationale JSONB, generated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(investor_profile_id, eco_partner_profile_id)); ALTER TABLE public.ecosystem_investor_match_scores ENABLE ROW LEVEL SECURITY;
